    // Optimized schedule
    // -----------------------------

    Target target = get_host_target();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) vec_width = 1;

    // Mean computation: one reduction per column j.
    // Parallelize across columns, vectorize across them as well.
    mean_sum
        .compute_root()
        .parallel(j)
        .vectorize(j, vec_width);

    mean
        .compute_root()
        .parallel(j)
        .vectorize(j, vec_width);

