    //
    // cov_sum is a 2D reduction over i,j with reduction var r_samples.
    //  - compute_root(): materialize full MxM partial sums once
    //  - parallelize across columns j (independent), which distributes
    //    work cleanly across cores
    //  - vectorize across i (row index in cov matrix), which is the
    //    innermost and contiguous dimension in memory
    cov_sum
        .compute_root()
        .parallel(j)
        .vectorize(i, vec_width);

    // Schedule the update step (the reduction) similarly: same
    // parallelization / vectorization pattern.
    cov_sum
        .update()
        .parallel(j)
        .vectorize(i, vec_width);

    // Final scaling stage: one pass over the MxM matrix.
    covariance
        .compute_root()
        .parallel(j)
        .vectorize(i, vec_width);

    // Bind runtime parameters.
    data_param.set(data);
    float_n_param.set(float_n);

    // JIT-compile the final stage for the chosen target.
    covariance.compile_jit(target);

    // -----------------------------
    // Run and time the kernel
    // -----------------------------

    auto start = std::chrono::high_resolution_clock::now();

    // Realize the covariance matrix into 'cov'.
    covariance.realize(cov);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -----------------------------
    // Print results (optional)
    // -----------------------------

    using namespace std::string_literals;

