#include "Halide.h"

// include common PolyBench-style definitions (problem sizes, DATA_TYPE, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (N, M, etc.)
#include "covariance.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// ------------------------------------------------------------------------------------
// Initialize the input array, matching the original C code semantics.
// ------------------------------------------------------------------------------------
static void init_array(int m, int n,
                       num_t *float_n,
                       Halide::Buffer<num_t, 2> data) {
    // float_n = (DATA_TYPE)n;
    *float_n = (num_t)n;

    // C code:
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < M; j++)
    //     data[i][j] = ((DATA_TYPE) i*j) / M;
    //
    // C array data[i][j] is mapped to Buffer data(j, i):
    Var i("i"), j("j");
    Func init_data("init_data");

    init_data(j, i) = cast<num_t>(i * j) / cast<num_t>(m);

    // -----------------------------
    // Schedule for initialization
    // -----------------------------
    // data has shape (m, n): x=j is contiguous in memory, y=i is rows.
    // Vectorize over x (j) for good use of SIMD, parallelize across rows.
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size<num_t>();

    init_data
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    // Realize into the provided buffer.
    init_data.realize(data);
}

int main(int argc, char *argv[]) {
    // Problem size (from covariance.hpp / defines.hpp)
    int n = N;
    int m = M;

    // Scalar and arrays.
    num_t float_n;

    // C: DATA_TYPE data[N][M];
    // Map to Halide: Buffer<num_t,2> data(M, N);  // (x = column j, y = row i)
    Halide::Buffer<num_t, 2> data(m, n);

    // C: DATA_TYPE cov[M][M];
    // Map to Halide: Buffer<num_t,2> cov(M, M);
    Halide::Buffer<num_t, 2> cov(m, m);

    // Initialize data and float_n.
    init_array(m, n, &float_n, data);

    // -----------------------------
    // Build the Halide pipeline
    // -----------------------------

    // ImageParam for the input data matrix.
    // data[i][j] in C is data_param(j, i) here (x = column j, y = row i).
    ImageParam data_param(type_of<num_t>(), 2, "data_param");

    // Scalar parameter float_n.
    Param<num_t> float_n_param("float_n_param");

    // We use:
    //   row: sample index (0..N-1)
    //   col: feature/column index (0..M-1)
    //   p,q: covariance matrix indices (0..M-1)
    Var row("row"), col("col");
    Var p("p"), q("q");

    // 1. Compute column means:
    //
    // C code:
    // for (j = 0; j < M; j++) {
    //   mean[j] = 0;
    //   for (i = 0; i < N; i++)
    //     mean[j] += data[i][j];
    //   mean[j] /= float_n;
    // }
    //
    // data[i][j] -> data_param(j, i) -> data_param(col, row)
    Func mean_sum("mean_sum"), mean("mean");
    RDom r_rows(0, data_param.dim(1).extent(), "r_rows");  // iterate over rows i = 0..n-1

    mean_sum(col) = cast<num_t>(0);
    mean_sum(col) += data_param(col, r_rows);       // sum over all rows for each column
    mean(col) = mean_sum(col) / float_n_param;      // divide by float_n

    // 2. Center the data by subtracting the mean from each column:
    //
    // C code:
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < M; j++)
    //     data[i][j] -= mean[j];
    //
    // We define a new Func 'centered' instead of modifying data in-place:
    // centered(row, col) corresponds to data[row][col] - mean[col].
    Func centered("centered");
    centered(row, col) = data_param(col, row) - mean(col);

    // 3. Compute the covariance matrix:
    //
    // C code:
    // for (i = 0; i < M; i++)
    //   for (j = i; j < M; j++) {
    //     cov[i][j] = 0;
    //     for (k = 0; k < N; k++)
    //       cov[i][j] += data[k][i] * data[k][j];
    //     cov[i][j] /= (float_n - 1.0);
    //     cov[j][i] = cov[i][j];
    //   }
    //
    // Here we compute the full MxM covariance as:
    // cov(p,q) = sum_k centered(k,p) * centered(k,q) / (float_n - 1)
    Func cov_sum("cov_sum"), covariance("covariance");
    RDom r_samples(0, data_param.dim(1).extent(), "r_samples");  // k = 0..n-1

    cov_sum(p, q) = cast<num_t>(0);
    cov_sum(p, q) += centered(r_samples, p) * centered(r_samples, q);

    // Precompute 1 / (float_n - 1) once as an Expr; this avoids a division per product.
    Expr inv_n_minus_1 = cast<num_t>(1) / (float_n_param - cast<num_t>(1));
    covariance(p, q) = cov_sum(p, q) * inv_n_minus_1;

    // -----------------------------
    // Optimized schedule
    // -----------------------------

    Target target = get_host_target();
    const int vec_width = target.natural_vector_size<num_t>();

    // ---- Mean computation ----
    //
    // mean_sum is a 1D reduction over rows for each column.
    // We parallelize across columns and vectorize inside each parallel chunk.
    {
        Var co("co"), ci("ci");

        // Compute all column sums at root.
        mean_sum.compute_root();

        // Schedule the update (reduction) step:
        mean_sum.update()
            .split(col, co, ci, 64)   // column tiles of size 64
            .parallel(co)             // parallel over column tiles
            .vectorize(ci, vec_width);

        // Finish mean on root, vectorized+parallel over columns
        mean.compute_root()
            .split(col, co, ci, 64)
            .parallel(co)
            .vectorize(ci, vec_width);
    }

    // ---- Covariance computation ----
    //
    // cov_sum is a 2D reduction over (p,q) with RDom over samples.
    // Work is O(M^2 * N), so we:
    //   * tile (p,q) to improve cache locality on cov_sum and covariance
    //   * parallelize across tiles of p
    //   * vectorize across q inside each tile
    {
        Var po("po"), qo("qo"), pi("pi"), qi("qi");

        const int tile_p = 32;                  // tile size along p (features)
        const int tile_q = 32;                  // tile size along q (features)

        // Allocate storage for the full covariance sums at root.
        cov_sum.compute_root();

        // Reduction update: for each sample k, update a tile of cov_sum.
        cov_sum.update()
            .tile(p, q, po, qo, pi, qi, tile_p, tile_q)
            .parallel(po)               // parallel across tiles in p
            .vectorize(qi, vec_width);  // vectorize across q within a tile

        // Final scaling stage: read cov_sum and write covariance, using same tiling.
        covariance
            .compute_root()
            .tile(p, q, po, qo, pi, qi, tile_p, tile_q)
            .parallel(po)
            .vectorize(qi, vec_width);
    }

    // Bind runtime parameters.
    data_param.set(data);
    float_n_param.set(float_n);

    // JIT-compile the final stage for this host target.
    covariance.compile_jit(target);

    // -----------------------------
    // Run and time the kernel
    // -----------------------------

    auto start = std::chrono::high_resolution_clock::now();

    // Realize the covariance matrix into 'cov'.
    covariance.realize(cov);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -----------------------------
    // Print results (optional)
    // -----------------------------

    using namespace std::string_literals;

    // As in the GEMM example, print the output to prevent dead-code elimination,
    // and provide a basic correctness check if desired.
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < m; jj++) {
                // C cov[ii][jj] -> Halide cov(jj, ii) due to (x=j, y=i) mapping.
                std::cerr << cov(jj, ii) << '\n';
            }
        }
    }

    // Print timing in seconds.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
