#include <iostream>
#include <string>

#include "Halide.h"

// include common PolyBench-style definitions (problem sizes, DATA_TYPE, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (N, M, etc.)
#include "covariance.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Tuneable tiling sizes for covariance computation.
// These can be adjusted for different cache sizes / core counts.
constexpr int TILE_I = 32;  // tile size in the fast (x) dimension
constexpr int TILE_J = 32;  // tile size in the slow (y) dimension

// Initialize the input array, matching the original C code semantics.
static void init_array(int m, int n,
                       num_t *float_n,
                       Halide::Buffer<num_t, 2> data) {
    // float_n = (DATA_TYPE)n;
    *float_n = (num_t)n;

    // C code:
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < M; j++)
    //     data[i][j] = ((DATA_TYPE) i*j) / M;
    //
    // C array data[i][j] is mapped to Buffer data(j, i):
    Var i("i"), j("j");
    Func init_data("init_data");

    init_data(j, i) = cast<num_t>(i * j) / cast<num_t>(m);

    // Simple CPU schedule for initialization:
    //  - parallelize across rows (i),
    //  - vectorize across columns (j).
    Target target = get_host_target();
    const int vec = target.natural_vector_size(type_of<num_t>());

    init_data
        .parallel(i)
        .vectorize(j, vec);

    // data has shape (m, n): width = M (columns), height = N (rows).
    init_data.realize(data);
}

int main(int argc, char *argv[]) {
    // Problem size (from covariance.hpp / defines.hpp)
    int n = N;
    int m = M;

    // Scalar and arrays.
    num_t float_n;

    // C: DATA_TYPE data[N][M];
    // Map to Halide: Buffer<num_t,2> data(M, N);  // (x = column j, y = row i)
    Halide::Buffer<num_t, 2> data(m, n);

    // C: DATA_TYPE cov[M][M];
    // Map to Halide: Buffer<num_t,2> cov(M, M);
    Halide::Buffer<num_t, 2> cov(m, m);

    // Initialize data and float_n.
    init_array(m, n, &float_n, data);

    // -----------------------------
    // Build the Halide pipeline
    // -----------------------------

    // ImageParam for the input data matrix.
    ImageParam data_param(type_of<num_t>(), 2, "data_param");

    // Scalar parameter float_n.
    Param<num_t> float_n_param("float_n_param");

    Var i("i"), j("j");

    // 1. Compute column means:
    //
    // C code:
    // for (j = 0; j < M; j++) {
    //   mean[j] = 0;
    //   for (i = 0; i < N; i++)
    //     mean[j] += data[i][j];
    //   mean[j] /= float_n;
    // }
    //
    // data[i][j] -> data_param(j, i)
    Func mean_sum("mean_sum"), mean("mean");
    // Iterate over rows i = 0..n-1
    RDom r_rows(0, data_param.dim(1).extent(), "r_rows");

    mean_sum(j) = cast<num_t>(0);
    mean_sum(j) += data_param(j, r_rows);   // sum over rows
    mean(j) = mean_sum(j) / float_n_param;  // divide by float_n

    // 2. Center the data by subtracting the mean from each column:
    //
    // C code:
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < M; j++)
    //     data[i][j] -= mean[j];
    //
    // We define a new Func 'centered' instead of modifying data in-place.
    Func centered("centered");
    centered(j, i) = data_param(j, i) - mean(j);

    // 3. Compute the covariance matrix:
    //
    // Original C code:
    // for (i = 0; i < M; i++)
    //   for (j = i; j < M; j++) {
    //     cov[i][j] = 0;
    //     for (k = 0; k < N; k++)
    //       cov[i][j] += data[k][i] * data[k][j];
    //     cov[i][j] /= (float_n - 1.0);
    //     cov[j][i] = cov[i][j];
    //   }
    //
    // Here we compute the full MxM covariance as:
    //   cov(i,j) = sum_k centered(i,k) * centered(j,k) / (float_n - 1)
    // expressed as a single reduction Func. This avoids storing an
    // extra intermediate cov_sum[] and improves locality.
    Func covariance("covariance");
    RDom r_samples(0, data_param.dim(1).extent(), "r_samples");  // k = 0..n-1

    // Precompute the scaling factor 1 / (float_n - 1) as an Expr;
    // Halide will hoist this out of the inner loops.
    Expr inv_n_minus_1 =
        cast<num_t>(1) / (float_n_param - cast<num_t>(1));

    covariance(i, j) = cast<num_t>(0);
    covariance(i, j) += centered(i, r_samples) *
                        centered(j, r_samples) *
                        inv_n_minus_1;

    // -----------------------------
    // Scheduling
    // -----------------------------

    // Get target info for a reasonable vector-width choice.
    Target target = get_host_target();
    const int vec = target.natural_vector_size(type_of<num_t>());

    // 1) Column means (1D reduction over rows)
    //
    // We compute mean_sum and mean at the root:
    //   - mean_sum: parallel & vectorized across columns j
    //   - mean:     same
    //
    // This matches the phase structure of the C reference, but
    // exploits multi-core parallelism across independent columns.
    mean_sum.compute_root();
    mean_sum
        .vectorize(j, vec)
        .parallel(j);
    mean_sum.update()
        .vectorize(j, vec)
        .parallel(j);

    mean.compute_root()
        .vectorize(j, vec)
        .parallel(j);

    // 2) Covariance (2D reduction over samples r_samples)
    //
    // We tile the (i,j) output space for better cache locality and
    // parallelize over tiles in the j (outer) dimension. Inside each
    // tile we vectorize across the fast i-dimension.
    //
    // The schedule is applied both to the pure definition (initial
    // zeroing) and to the reduction update.
    Var io("io"), jo("jo"), ii("ii"), ji("ji");

    covariance.compute_root();
    // Pure definition: cov(i,j) = 0
    covariance
        .tile(i, j, io, jo, ii, ji, TILE_I, TILE_J)
        .parallel(jo)          // distribute tiles over cores
        .vectorize(ii, vec);   // SIMD across contiguous i

    // Reduction update: cov(i,j) += ...
    covariance.update()
        .tile(i, j, io, jo, ii, ji, TILE_I, TILE_J)
        .parallel(jo)
        .vectorize(ii, vec);

    // Note: 'centered' is left inlined into covariance. It is a tiny
    // expression (data_param(j,i) - mean(j)), so inlining avoids
    // allocating extra storage and keeps data in registers.

    // -----------------------------
    // Bind runtime parameters
    // -----------------------------

    data_param.set(data);
    float_n_param.set(float_n);

    // JIT-compile the final stage for the chosen target.
    covariance.compile_jit(target);

    // -----------------------------
    // Run and time the kernel
    // -----------------------------

    auto start = std::chrono::high_resolution_clock::now();

    // Realize the covariance matrix into 'cov'.
    covariance.realize(cov);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -----------------------------
    // Print results (optional)
    // -----------------------------

    using namespace std::string_literals;

    // As in the GEMM example, print the output to prevent dead-code elimination,
    // and provide a basic correctness check if desired.
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < m; jj++) {
                // C cov[ii][jj] -> Halide cov(jj, ii)
                std::cerr << cov(jj, ii) << '\n';
            }
        }
    }

    // Print timing in seconds.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
