    //
    // NOTE: This produces the same numerical values as the C code for all
    // (i,j); the original C code only explicitly computed the upper
    // triangle and mirrored it, but the mathematical result is symmetric.
    Func cov_sum("cov_sum"), covariance("covariance");
    RDom r_samples(0, data_param.dim(1).extent(), "r_samples");  // k = 0..n-1

    cov_sum(i, j) = cast<num_t>(0);
    cov_sum(i, j) += centered(i, r_samples) * centered(j, r_samples);

    // Precompute reciprocal of (float_n - 1) (again, one division).
    Expr inv_float_n_minus_1 = cast<num_t>(1) / (float_n_param - cast<num_t>(1));
    covariance(i, j) = cov_sum(i, j) * inv_float_n_minus_1;

    // -----------------------------
    // Optimized schedule
    // -----------------------------

    // Target and natural vector width for this scalar type.
    Target target = get_jit_target_from_environment();
    const int vec_width = Halide::natural_vector_size<num_t>(target);

    // ---- Schedule for mean_sum / mean ----
    //
    // mean_sum is a reduction across rows (N) for each column (M).
    // We:
    //   - compute it at root,
    //   - parallelize across columns j,
    //   - vectorize across contiguous j when profitable.
    mean_sum.compute_root();
    if (vec_width > 1) {
        mean_sum.vectorize(j, vec_width);
    }
    mean_sum.parallel(j);

    // mean is a simple pointwise transform of mean_sum; keep it at root
    // so that it is computed once and then reused.
    mean.compute_root();
    if (vec_width > 1) {
        mean.vectorize(j, vec_width);
    }
    mean.parallel(j);

    // 'centered' remains inlined by default. It is very cheap
    // (just a subtraction) and is evaluated in the context of its consumers,
    // so we don't force a separate storage pass for it.

    // ---- Schedule for cov_sum (dominant cost) ----
    //
    // cov_sum is a 2D reduction over samples (N) that produces an MxM
    // matrix. We want to:
